// Backfill Run Config. Same authority/seniority/exclusion rules as W1's Run
// Config - kept in sync BY HAND, since separate n8n workflow files share no
// code. If W1's Run Config changes DM_SENIORITIES, OPS_TITLES, or the
// exclude regexes, mirror the change here too.
const DM_SENIORITIES = ['owner', 'founder', 'c_suite', 'partner', 'vp', 'director'];
const OPS_TITLES = {
  law_firm: ['Chief Operating Officer', 'Director of Operations', 'Practice Group Leader',
             'Firm Administrator', 'Legal Administrator', 'Director of Intake'],
  medical: ['Office Manager', 'Practice Manager', 'Practice Administrator',
            'Dental Office Manager', 'Head of Operations', 'Director of Operations'],
  home_services: ['General Manager', 'Operations Manager', 'Director of Operations',
                  'Dispatcher', 'Dispatch Manager', 'Service Manager'],
};

return [{
  json: {
    // Set by the installer from whether APOLLO_KEY is configured - do NOT
    // flip this by hand, same rule as W1's Run Config: true with no
    // credential fails every Apollo node mid-run.
    useApollo: false,
    // How many existing business-only prospects to reveal an email for this
    // run. Search (step 2) is free regardless of this cap - only the reveal
    // in step 3 spends a credit. Same name, same meaning as W1's own cap,
    // just spent against the backlog instead of fresh discoveries. Installer
    // sets it from APOLLO_REVEALS, same as W1.
    maxRevealsPerRun: 25,
    // Phone is the front of the SAME best-first list, a separate and much
    // tighter budget - confirmed live at 8 credits a reveal, not ~1 like
    // email. Installer sets it from APOLLO_PHONE_REVEALS, same as W1.
    maxPhoneRevealsPerRun: 0,
    excludeTitleRe: 'receptionist|paralegal|assistant|chief content|content officer|editor-in-chief|publisher',
    excludeCompanyRe: 'marketing|agency|agencies|automation|\\bai\\b|artificial intelligence|software|saas|consult|growth partner|lead gen|supplies|\\bsupply\\b|wholesale|distribut|telecom|networking|\\bcloud\\b|\\blabs\\b|magazine|association',
    personSeniorities: DM_SENIORITIES,
    opsTitles: OPS_TITLES,
  },
}];

// Candidates already arrive best-first (tier asc, intent desc - the SQL
// query in 'Get Backfill Candidates' did that sort and applied the cap), so
// position in this list IS priority order. Phone reveal is a subset of that
// SAME order, the front maxPhoneRevealsPerRun of it - never a separate
// selection, same rule as W1's Cap Reveals.
const cfg = $('Run Config').first().json;
const items = $input.all().map((i) => i.json);
return items.map((x, i) => ({ json: { ...x, needsPhoneReveal: i < (cfg.maxPhoneRevealsPerRun || 0) } }));

// Combine both Apollo passes for this ONE already-known company and pick
// the best-ranked decision maker, using the EXACT same per-vertical
// authority ranking as W1's Filter & Dedupe - kept in sync by hand, no
// shared module between separate workflow files. No domain/phone dedupe
// here: unlike W1, the point of this workflow IS to revisit a company
// already in the table.
const cfg = $('Run Config').first().json;
const company = $('Per Backfill Candidate').first().json;

// Distinguishes "errored" from "ran fine, found nobody" - same reasoning
// as W1: conflating them is what made a silently-broken Apollo credential
// impossible to tell apart from a company Apollo genuinely has nobody for.
const apolloRunInfo = (node) => {
  try {
    const j = $(node).first().json || {};
    if (j && j.error) return { people: [], errored: true };
    if (Array.isArray(j.people)) return { people: j.people, errored: false };
    return { people: [], errored: false };
  } catch (e) { return { people: [], errored: false }; }
};
const seniorityInfo = apolloRunInfo('Apollo Search By Domain');
const opsInfo = apolloRunInfo('Apollo Search By Domain Ops');
const people = [...seniorityInfo.people, ...opsInfo.people];

const exTitle = new RegExp(cfg.excludeTitleRe, 'i');
const exCompany = new RegExp(cfg.excludeCompanyRe, 'i');

const AUTHORITY = [
  ['owner',      /\bowner\b|founder|principal|(?<!vice )\bpresident\b|\bceo\b|chief executive|managing (partner|attorney|director)|sole (attorney|practitioner)/],
  ['operations', /\bcoo\b|chief operating|(director|vp|vice president|head)\s+(of\s+)?operations|operations (manager|director)|general manager|\bgm\b|dispatch|service manager|practice group (leader|lead)|firm administrator|legal administrator/],
  ['office',     /office manager|practice (manager|administrator)|business manager|office administrator/],
  ['c_suite',    /\bchief\b|\bcfo\b|\bcmo\b|\bcto\b|\bcso\b/],
  ['partner',    /\bpartner\b/],
  ['marketing',  /marketing|\bintake\b|growth|business development|\bbiz dev\b|client relations|revenue/],
  ['leader',     /director|\bvp\b|vice president|\bhead of\b/],
  ['staff',      /manager|administrator|coordinator/],
];
const authority = (title) => {
  const t = String(title || '').toLowerCase();
  for (const [band, re] of AUTHORITY) if (re.test(t)) return band;
  return 'staff';
};
const RANK = {
  law_firm:      { owner: 9, partner: 8, operations: 7, c_suite: 6, marketing: 5, office: 4, leader: 3, staff: 2 },
  medical:       { owner: 9, office: 8, operations: 7, c_suite: 6, marketing: 5, partner: 5, leader: 3, staff: 2 },
  home_services: { owner: 9, operations: 8, c_suite: 6, marketing: 5, partner: 5, office: 4, leader: 3, staff: 2 },
};
const DECIDES = {
  law_firm:      new Set(['owner', 'partner', 'operations', 'c_suite', 'marketing']),
  medical:       new Set(['owner', 'office', 'operations', 'c_suite', 'marketing']),
  home_services: new Set(['owner', 'operations', 'c_suite', 'marketing']),
};
const rankOf = (title) => (RANK[company.vertical] || RANK.home_services)[authority(title)] || 0;
const decides = (title) => (DECIDES[company.vertical] || DECIDES.home_services).has(authority(title));

let best = null;
for (const person of people) {
  const org = person.organization || {};
  if (exTitle.test(person.title || '')) continue;
  if (exCompany.test(org.name || company.company_name || '')) continue;
  const emp = org.estimated_num_employees ?? null;
  if (emp !== null && emp < 2) continue;
  if (!best || rankOf(person.title) > rankOf(best.title)) best = person;
}

if (!best) {
  return [{ json: { ...company, found: false } }];
}

return [{ json: {
  ...company,
  apollo_person_id: best.id || null,
  contact_name: best.name || [best.first_name, best.last_name].filter(Boolean).join(' ') || company.contact_name || null,
  contact_title: best.title || null,
  contact_authority: authority(best.title),
  decision_maker: decides(best.title),
  contact_linkedin_url: best.linkedin_url || company.contact_linkedin_url || null,
  found: true,
} }];

// n8n's text-format output lands the raw body under different keys across
// versions ('data' in current builds, 'body' in older ones) - same fallback
// W1 uses for the identical Apollo response shape.
const item = $input.item.json || {};
let raw = item.data ?? item.body ?? (typeof item === 'string' ? item : '');
if (raw && typeof raw === 'object') raw = JSON.stringify(raw);
raw = String(raw || '');

let parsed = {};
try { parsed = JSON.parse(raw); } catch (e) { parsed = {}; }
const person = parsed.person || {};

// request_id can exceed Number.MAX_SAFE_INTEGER - pulled as a STRING
// straight from the raw text, never through JSON.parse, same reason as W1.
const idMatch = raw.match(/"request_id"\s*:\s*(-?\d+)/);
const requestId = idMatch ? idMatch[1] : null;
const phoneRequested = !!parsed.phone_enrichment;

const rawPersonalEmails = Array.isArray(person.personal_emails) ? person.personal_emails : [];
const firstPersonal = rawPersonalEmails.length
  ? (typeof rawPersonalEmails[0] === 'string'
      ? rawPersonalEmails[0]
      : (rawPersonalEmails[0].email || rawPersonalEmails[0].address || rawPersonalEmails[0].value || null))
  : null;

return { json: {
  person, phoneRequested, phoneRequestId: phoneRequested ? requestId : null,
  personalEmail: firstPersonal,
} };

// Attach the revealed business email (never personal) to the prospect.
// Same logic as W1's Attach Contact, reading from THIS workflow's loop node.
const company = $('Pick Best Person').first().json;
const parsed = $input.first().json || {};
const person = parsed.person || {};
const email = person.email && !String(person.email).includes('email_not_unlocked') ? person.email : null;

// Apollo obfuscates/omits last names in SEARCH results unless the plan
// includes full-reveal-in-search - same behavior W1 documents. Only ever
// upgrades a partial name to a fuller one; never downgrades.
const enrichedName = person.name || [person.first_name, person.last_name].filter(Boolean).join(' ') || null;
const looksPartial = (n) => !n || !String(n).trim().includes(' ');
const contactName = (enrichedName && looksPartial(company.contact_name) && !looksPartial(enrichedName))
  ? enrichedName
  : (company.contact_name || null);

// Phone is never in this response (verified live on W1 twice). contact_phone
// is deliberately NOT touched here or in the write step below - it is set
// only once the async request_id resolves, by W1's OWN 'Update Prospect
// Phone' side-branch, which polls ANY pending id regardless of which
// workflow originally requested it.
//
// 'Apollo Enrich Person' sends webhook_url whenever needsPhoneReveal is
// true - confirmed live 2026-08 that Apollo hard-rejects the call with 400
// without it, even though retrieval here is entirely by polling, same as W1.
const nowIso = new Date().toISOString();
return [{ json: {
  ...company,
  contact_name: contactName,
  contact_email: email || company.contact_email || null,
  contact_email_personal: parsed.personalEmail || company.contact_email_personal || null,
  contact_linkedin_url: company.contact_linkedin_url || person.linkedin_url || null,
  phone_reveal_request_id: parsed.phoneRequestId || company.phone_reveal_request_id || null,
  phone_reveal_requested_at: parsed.phoneRequestId ? nowIso : (company.phone_reveal_requested_at || null),
} }];
